package com.citacloud.springboot.contacloud.app.mappers;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import org.springframework.stereotype.Component;import java.math.BigDecimal;import java.util.*;
@Component public class SupplierCreditNoteMapper{
 public NotaCreditoProveedorDto toDto(NotaCreditoProveedor n,BigDecimal saldoFactura,List<AplicacionNotaCreditoProveedorDto> aplicaciones,boolean detail){FacturaProveedor f=n.getFacturaRelacionada();return new NotaCreditoProveedorDto(n.getId(),n.getNumero(),n.getFecha(),n.getProveedorId(),n.getProveedor()==null?null:n.getProveedor().getNombreComercial(),n.getProveedor()==null?null:n.getProveedor().getIdentificacionFiscal(),n.getNumeroProveedor(),n.getNumeroFiscal(),n.getMonedaId(),n.getMoneda()==null?null:n.getMoneda().getCodigoIso(),n.getTasaCambio(),n.getMotivo(),n.getOtroMotivo(),n.getFacturaRelacionadaId(),f==null?null:f.getNumeroProveedor(),f==null?null:f.getFecha(),f==null?null:f.getTotal(),saldoFactura,n.getNotas(),n.getSubtotal(),n.getDescuento(),n.getImpuesto(),n.getTotal(),n.getAplicado(),n.disponible(),n.getEstado(),n.getVersion(),n.getMotivoAnulacion(),detail?n.getLineas().stream().map(this::line).toList():List.of(),aplicaciones);}
 private LineaNotaCreditoProveedorDto line(LineaNotaCreditoProveedor l){return new LineaNotaCreditoProveedorDto(l.getId(),l.getLineaFacturaId(),l.getProductoId(),l.getCodigoProducto(),l.getDescripcion(),l.getUnidad(),l.getCantidadFacturada(),l.getCantidad(),l.getPrecio(),l.getDescuento(),l.getImpuestoId(),l.getImpuestoNombre(),l.getImpuesto(),l.getSubtotal(),l.getTotal());}
}
